// AWI: rapikan tampilan tema (jam buka, ticker, format harga Rp, Dolphin tanpa harga, link Harga, "stok terbatas" maks 1x per halaman)
add_action( 'template_redirect', function () {
	if ( is_admin() || wp_doing_ajax() || is_feed() || ( defined( 'REST_REQUEST' ) && REST_REQUEST ) ) {
		return;
	}
	ob_start( 'awi_rapi_html' );
}, 98 );

function awi_rapi_html( $html ) {
	if ( ! is_string( $html ) || false === stripos( $html, '<body' ) ) {
		return $html;
	}
	$pos  = stripos( $html, '<body' );
	$head = substr( $html, 0, $pos );
	$body = substr( $html, $pos );

	// 1) Jam buka: status buka/tutup tema ikut ter-cache, ganti dengan jadwal tetap.
	$body = preg_replace(
		'#<span class="onandoff">[^<]*</span>\s*<span class="(?:closehour|openhour)">[^<]*</span>#',
		'<span class="onandoff" style="white-space:nowrap">Sen–Sab 08–17 · Min 09–17 WITA</span>',
		$body
	);

	// 2) Ticker & popup: buang kalimat desakan.
	$body = str_replace( 'OTR Makassar. Stok terbatas, harga terbaik bulan ini. Chat AWI', 'OTR Makassar. Chat AWI', $body );
	$body = str_replace( ' Stok terbatas.</div>', '</div>', $body );
	$body = str_replace( 'harga OTR, stok terbatas bulan ini, atau simulasi cicilan?', 'harga OTR, ketersediaan unit, atau simulasi cicilan?', $body );

	// 3) "Stok terbatas, harga terbaik bulan ini" maksimal 1x per halaman.
	$n    = 0;
	$body = preg_replace_callback(
		'#\s?Stok terbatas, harga terbaik bulan ini(\.|,\s*jadi cek| bisa)#',
		function ( $m ) use ( &$n ) {
			$n++;
			if ( 1 === $n ) {
				return $m[0];
			}
			if ( '.' === $m[1] ) {
				return '';
			}
			if ( ' bisa' === $m[1] ) {
				return ' Harga terbaik bulan ini bisa';
			}
			return ' Cek';
		},
		$body
	);

	// 4) Format harga seragam "Rp".
	$body = preg_replace( '#\bIDR\s*(\d{1,3}(?:\.\d{3})+)#', 'Rp$1', $body );
	$body = preg_replace_callback(
		'#<span class="price__number">\s*([\d.,]+)\s*Jutaan\s*</span>#i',
		function ( $m ) {
			$v = (float) str_replace( array( '.', ',' ), array( '', '.' ), $m[1] );
			if ( $v >= 1000 ) {
				$txt = 'Rp' . rtrim( rtrim( number_format( $v / 1000, 3, ',', '.' ), '0' ), ',' ) . ' miliar';
			} else {
				$txt = 'Rp' . rtrim( rtrim( number_format( $v, 1, ',', '.' ), '0' ), ',' ) . ' juta';
			}
			return '<span class="price__number">' . $txt . '</span>';
		},
		$body
	);

	$body = preg_replace_callback(
		'#<span class="price__number">\s*([\d.,]+)\s*Milyar\s*</span>#i',
		function ( $m ) {
			return '<span class="price__number">Rp' . str_replace( '.', ',', $m[1] ) . ' miliar</span>';
		},
		$body
	);

	// 5) Dolphin (tanpa harga di pricelist): jangan tampil "0 Tipe" / judul kosong di tabel harga.
	$body = str_replace( '<span class="dealer_model_car_type">0 Tipe</span>', '<span class="dealer_model_car_type">Tanya stok</span>', $body );
	$body = str_replace( '<span class="little">0 Tipe</span>', '<span class="little">Tanya stok</span>', $body );
	$body = str_replace( '<div class="all_ava">Varian: 0 Tipe</div>', '<div class="all_ava">Varian: tanya stok</div>', $body );
	$body = preg_replace(
		'#<tr>\s*<td colspan="2">\s*<div class="pricelist__title">BYD Dolphin</div>\s*</td>\s*</tr>\s*(?=<tr>\s*<td colspan="2">|</tbody>|</table>)#',
		'',
		$body
	);

	// 7) Kartu testimoni: buang pembungkus ".." tema, pisah baris model & kutipan, alt foto per pelanggan.
	if ( false !== strpos( $body, 'test__extitle' ) ) {
		$body = preg_replace_callback(
			'#<div class="test__extitle">([^<]*)</div>\s*"\.\.(.*?)\.\."\s*</div>#s',
			function ( $m ) {
				$txt = trim( $m[2] );
				$txt = preg_replace( '#^(?:&\#8220;|")?\.\.\s*#', '', $txt );
				if ( preg_match( '#^(Serah terima .+?)(?:\s|&nbsp;)+(?:—|&\#8212;)(?:\s|&nbsp;)+(.*)$#su', $txt, $p ) ) {
					$txt = '<div class="awi-tm" style="font-size:13px;font-weight:700;color:#0b5394;margin:2px 0 6px">' . $p[1] . '</div><div class="awi-tq">' . $p[2] . '</div>';
				}
				return '<div class="test__extitle">' . $m[1] . '</div>' . $txt . '</div>';
			},
			$body
		);
		$body = preg_replace_callback(
			'#(<div class="test__block">)(.*?)(<div class="test__extitle">([^<]*)</div>)#s',
			function ( $m ) {
				$alt  = 'Serah terima mobil BYD ke ' . trim( $m[4] ) . ' – BYD Haka Karebosi Makassar';
				$imgs = preg_replace( '#\salt="[^"]*"#', '', $m[2] );
				$imgs = str_replace( '<img ', '<img alt="' . esc_attr( $alt ) . '" ', $imgs );
				return $m[1] . $imgs . $m[3];
			},
			$body
		);
	}

	// 8) Tombol ulasan Google di halaman Testimoni.
	if ( false !== strpos( $body, 'testimoni__archive' ) && false === strpos( $body, 'awi-greview' ) ) {
		$btn  = 'display:inline-block;padding:10px 14px;border-radius:8px;font-weight:700;text-decoration:none;font-size:14px;margin:0 8px 8px 0';
		$blk  = '<div class="awi-greview" style="margin:0 0 20px">';
		$blk .= '<a href="https://maps.app.goo.gl/UnBCgN8yNyF5MNrZ8" target="_blank" rel="noopener" style="' . $btn . ';background:#fff;border:1px solid #cbd5e1;color:#0f172a">⭐ Lihat ulasan pelanggan di Google Maps</a>';
		$blk .= '<a href="https://search.google.com/local/writereview?placeid=ChIJ_x3gFVIDvy0RRQiO3qClxJg" target="_blank" rel="noopener" style="' . $btn . ';background:#0b5394;color:#fff">Sudah beli dari AWI? Beri ulasan</a>';
		$blk .= '</div>';
		$body = preg_replace( '#(<h1 class="archive__title"><span class="testimoni__archive">.*?</span></h1>)#s', '$1' . $blk, $body, 1 );
	}

	// 9) Info penting pembeli EV (charging, garansi baterai, servis) di beranda & halaman model.
	if ( false === strpos( $body, 'awi-evinfo' ) && ( false !== strpos( $body, 'single-model' ) || false !== strpos( $body, 'page-id-10496' ) ) ) {
		$u    = 'https://byd-makassar.id/charging-garansi-servis-byd-makassar/';
		$card = 'display:block;text-decoration:none;color:#0f172a;border-radius:12px;padding:12px 14px';
		$ev   = '<div class="awi-evinfo" style="margin:18px 0 26px">';
		$ev  .= '<p style="font-size:18px;font-weight:800;margin:0 0 10px;color:#0f172a">Sebelum beli mobil listrik, cek 3 hal ini</p>';
		$ev  .= '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:10px">';
		$ev  .= '<a href="' . $u . '#peta" style="' . $card . ';background:#ecfdf5;border:1px solid #a7f3d0"><b>⚡ Charging di Makassar</b><br><span style="font-size:14px;color:#334155">Utama di rumah + SPKLU PLN se-Sulsel. Lihat peta SPKLU &amp; rute antarkota →</span></a>';
		$ev  .= '<a href="' . $u . '#garansi" style="' . $card . ';background:#eff6ff;border:1px solid #bfdbfe"><b>🔋 Garansi baterai 8 tahun</b><br><span style="font-size:14px;color:#334155">160.000 km (SoH ≥70%), kendaraan 6 tahun. Tetap berlaku saat dijual lagi →</span></a>';
		$ev  .= '<a href="' . $u . '#servis" style="' . $card . ';background:#fff7ed;border:1px solid #fed7aa"><b>🛠️ Servis di Makassar</b><br><span style="font-size:14px;color:#334155">Servis berkala & klaim garansi di bengkel resmi, dibantu AWI →</span></a>';
		$ev  .= '</div></div>';
		if ( false !== strpos( $body, 'single-model' ) ) {
			$body = preg_replace( '#<!-- awi-geo-end -->(\s*</p>)?#', '$0' . $ev, $body, 1 );
		} else {
			$body = preg_replace( '#(<h2[^>]*>Berapa hemat pakai mobil listrik di Makassar\?</h2>)#', $ev . '$1', $body, 1 );
		}
	}

	// 10) Peta SPKLU interaktif (Google Maps, selalu update) di halaman Charging, Garansi & Servis.
	if ( false !== strpos( $body, 'page-id-10597' ) && false === strpos( $body, 'awi-spklu-map' ) ) {
		$g    = 'https://maps.google.com/maps?hl=id&z=12&output=embed&q=';
		$chip = 'cursor:pointer;border:1px solid #0b5394;background:#fff;color:#0b5394;font-weight:700;font-size:14px;padding:7px 12px;border-radius:999px;margin:0 6px 8px 0';
		$set  = "document.getElementById('awi-spklu-map').src=";
		$kota = array( 'Makassar' => 'SPKLU Makassar', 'Gowa' => 'SPKLU Gowa', 'Maros' => 'SPKLU Maros', 'Parepare' => 'SPKLU Parepare', 'Bone' => 'SPKLU Watampone', 'Bulukumba' => 'SPKLU Bulukumba', 'Toraja' => 'SPKLU Toraja' );
		$map  = '<div id="peta" style="margin:10px 0 22px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:14px;padding:14px">';
		$map .= '<p style="font-size:18px;font-weight:800;margin:0 0 4px">🗺️ Peta SPKLU Makassar &amp; Sulawesi Selatan</p>';
		$map .= '<p style="font-size:14px;color:#475569;margin:0 0 10px">Titik charging diambil langsung dari Google Maps, jadi lokasi baru ikut muncul otomatis. Pilih kota atau tekan <b>Dekat saya</b>.</p>';
		$map .= '<div>';
		$map .= '<button type="button" style="' . $chip . ';background:#0b5394;color:#fff" onclick="var b=this;if(!navigator.geolocation){alert(\'Lokasi tidak didukung browser\');return;}b.textContent=\'Mencari…\';navigator.geolocation.getCurrentPosition(function(p){' . $set . '\'' . $g . 'SPKLU&amp;ll=\'+p.coords.latitude+\',\'+p.coords.longitude;b.textContent=\'📍 Dekat saya\';},function(){b.textContent=\'📍 Dekat saya\';alert(\'Izinkan akses lokasi untuk melihat SPKLU terdekat\');})">📍 Dekat saya</button>';
		foreach ( $kota as $label => $q ) {
			$map .= '<button type="button" style="' . $chip . '" onclick="' . $set . '\'' . $g . rawurlencode( $q ) . '\'">' . $label . '</button>';
		}
		$map .= '</div>';
		$map .= '<iframe id="awi-spklu-map" title="Peta SPKLU Makassar" src="' . $g . rawurlencode( 'SPKLU Makassar' ) . '" style="width:100%;height:420px;border:0;border-radius:10px;background:#e2e8f0" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe>';
		$map .= '<div style="margin-top:10px">';
		$map .= '<a href="https://www.google.com/maps/search/SPKLU/@-5.1477,119.4327,12z" target="_blank" rel="noopener" style="display:inline-block;margin:0 8px 8px 0;padding:10px 14px;border-radius:8px;background:#fff;border:1px solid #cbd5e1;color:#0f172a;font-weight:700;text-decoration:none;font-size:14px">Buka di Google Maps (rute) ↗</a>';
		$map .= '<a href="https://play.google.com/store/apps/details?id=com.icon.pln123" target="_blank" rel="noopener" style="display:inline-block;margin:0 8px 8px 0;padding:10px 14px;border-radius:8px;background:#0b7a5a;color:#fff;font-weight:700;text-decoration:none;font-size:14px">Cek status charger real-time di PLN Mobile ↗</a>';
		$map .= '</div>';
		$map .= '<p style="font-size:13px;color:#64748b;margin:4px 0 0">Status charger (kosong, terpakai, gangguan) yang paling akurat ada di aplikasi PLN Mobile, menu SPKLU. Pengguna iPhone: cari "PLN Mobile" di App Store.</p>';
		$map .= '</div>';
		$body = preg_replace( '#(<h2 id="charging"[^>]*>.*?</h2>)#s', '$1' . $map, $body, 1 );
	}

	// 11) Gambar hotlink Blogger diganti salinan lokal yang sudah dikompres (peta dari snippet impor).
	if ( false !== strpos( $body, 'blogger.googleusercontent.com' ) ) {
		$map = get_option( 'awi_img_map' );
		if ( is_array( $map ) && $map ) {
			$body = strtr( $body, array_filter( $map ) );
		}
	}

	// 13) Header beranda: slide foto semua unit BYD & Denza (CSS saja, ganti latar abu-abu kosong tema).
	if ( false !== strpos( $body, 'page-id-10496' ) && false === strpos( $body, 'awi-hs' ) ) {
		$up    = 'https://byd-makassar.id/wp-content/uploads/';
		$units = array(
			array( 'byd-atto-1', 'BYD Atto 1', 'Mulai Rp213 juta OTR', '2026/10/byd-atto-1-2026-makassar-hero.webp' ),
			array( 'byd-m6-dm', 'BYD M6 DM', 'Mulai Rp311,4 juta OTR', '2026/10/byd-m6-dm-makassar-hero-hd.webp' ),
			array( 'byd-m6', 'BYD M6', 'Mulai Rp414 juta OTR', '2026/06/m6-landscape.webp' ),
			array( 'byd-atto-3', 'BYD Atto 3', 'Rp435 juta OTR', '2026/10/byd-atto-3-makassar-hero.webp' ),
			array( 'byd-atto-2', 'BYD Atto 2', 'Segera hadir · inden dibuka', '2026/10/byd-atto-2-hero.webp' ),
			array( 'byd-ti7', 'BYD Ti7', 'Segera hadir · inden dibuka', '2026/10/byd-ti7-hero.webp' ),
			array( 'byd-dolphin', 'BYD Dolphin', 'Tanya ketersediaan', '2025/04/dolphin.webp' ),
			array( 'byd-seal', 'BYD Seal', 'Rp884 juta OTR', '2025/04/byd-seal-Aurora-White.webp' ),
			array( 'byd-sealion-7', 'BYD Sealion 7', 'Rp897 juta OTR', '2025/04/byd-sealion-7.webp' ),
			array( 'byd-denza-d9', 'Denza D9', 'Rp1,118 miliar OTR', '2026/10/denza-d9-makassar-hero.webp' ),
			array( 'byd-denza-z9-gt', 'Denza Z9 GT', 'Rp2,288 miliar OTR', '2026/10/denza-z9-gt-makassar-hero.webp' ),
		);
		$n   = count( $units );
		$dur = $n * 4;
		$css  = '<style>';
		$css .= '.awi-hs{position:relative;overflow:hidden;background:#0b1f33;height:clamp(240px,48vw,520px)}';
		$css .= '.awi-hs .awi-s{position:absolute;inset:0;opacity:0;visibility:hidden;animation:awiHs ' . $dur . 's infinite}';
		$css .= '.awi-hs .awi-s img{display:block;width:100%;height:100%;object-fit:cover}';
		$css .= '.awi-hs .awi-s a{position:absolute;left:4%;bottom:16px;z-index:5;background:rgba(255,255,255,.95);color:#0b1f33;font-weight:800;font-size:clamp(13px,1.6vw,17px);padding:8px 14px;border-radius:999px;text-decoration:none;box-shadow:0 4px 14px rgba(0,0,0,.25)}';
		$css .= '.awi-hs .awi-s a span{font-weight:600;color:#0b7a5a;margin-left:6px}';
		$css .= '.awi-hs:before,.awi-hs.thumb__background:after{display:none!important}.awi-hs .awi-s:after{content:"";position:absolute;left:0;right:0;bottom:0;height:65%;background:linear-gradient(0deg,rgba(6,15,26,.88),rgba(6,15,26,0));z-index:1;pointer-events:none}';
		$css .= '.awi-hs .single__top{position:absolute;top:auto;left:0;right:0;bottom:62px;width:auto;max-width:none;margin:0;padding:0 4%;z-index:4;pointer-events:none}';
		$css .= '.awi-hs .single__heading{color:#fff;text-align:left;margin:0;padding:0;line-height:1.2;font-size:clamp(20px,3.4vw,40px);text-shadow:0 2px 12px rgba(0,0,0,.45)}';
		$css .= '@keyframes awiHs{0%{opacity:0;visibility:visible}1.5%{opacity:1;visibility:visible}' . round( 100 / $n, 2 ) . '%{opacity:1;visibility:visible}' . round( 100 / $n + 1.5, 2 ) . '%{opacity:0;visibility:hidden}100%{opacity:0;visibility:hidden}}';
		$css .= '@media (prefers-reduced-motion:reduce){.awi-hs .awi-s{animation:none}.awi-hs .awi-s:first-child{opacity:1;visibility:visible}}';
		$css .= '</style>';
		$sl = '';
		foreach ( $units as $i => $u ) {
			$sl .= '<div class="awi-s" style="animation-delay:' . ( $i * 4 ) . 's">';
			$sl .= '<img data-no-lazy="1" src="' . $up . $u[3] . '" alt="' . esc_attr( $u[1] . ' di dealer resmi BYD Haka Karebosi Makassar' ) . '"' . ( 0 === $i ? ' fetchpriority="high"' : ' loading="lazy" decoding="async"' ) . ' width="1400" height="800">';
			$sl .= '<a href="https://byd-makassar.id/model/' . $u[0] . '/">' . $u[1] . '<span>' . $u[2] . ' →</span></a>';
			$sl .= '</div>';
		}
		$body = preg_replace(
			'#<div class="thumb__background" style="background-image: url\(\'\);">\s*(<div class="container single__top">\s*<h1 class="single__heading">.*?</h1>\s*</div>)\s*</div>#s',
			$css . '<div class="thumb__background awi-hs" style="padding:0;min-height:0">' . str_replace( '$', '\$', $sl ) . '$1</div>',
			$body,
			1
		);
	}

	// 12) Logo, foto AWI di header, dan gambar utama (loading="eager") langsung tampil, tidak menunggu lazy-load.
	$body = preg_replace_callback(
		'#<img\b(?![^>]*data-no-lazy)[^>]*>#i',
		function ( $m ) {
			$t = $m[0];
			if ( preg_match( '#class="[^"]*custom-logo|awi-nyd-makassar-50x50|loading="eager"#i', $t ) ) {
				$t = preg_replace( '#^<img\b#i', '<img data-no-lazy="1"' . ( false !== stripos( $t, 'loading="eager"' ) ? ' fetchpriority="high"' : '' ), $t );
			}
			return $t;
		},
		$body
	);

	// 14) Jam buka di HP: jangan mengambang menutupi tombol, taruh di baris alamat atas.
	$head = str_replace( '</head>', '<style id="awi-jam-mobile">@media (max-width:991px){.dealer_top .dealer_timework{position:static!important;inset:auto!important;top:auto!important;right:auto!important;bottom:auto!important;left:auto!important;transform:none!important;box-shadow:none!important;z-index:auto!important;display:block!important;margin:2px 0 0!important;padding:0!important;background:none!important;width:auto!important;text-align:left!important}.dealer_top .dealer_timework .onandoff{display:inline-block!important;font-size:12px!important;line-height:1.4!important;padding:2px 8px!important;border-radius:6px!important;box-shadow:none!important}}</style></head>', $head );

	// 6) Tombol "Harga" di bar bawah ke halaman daftar harga.
	$body = str_replace( '<a class="awi-price" href="https://byd-makassar.id/model/"', '<a class="awi-price" href="https://byd-makassar.id/harga-byd-makassar/"', $body );

	return $head . $body;
}
